example.code:
menu = ["Coffee", "Bagel", "Muffin"]
prices = [3, 5, 4]

for number, item in enumerate(menu, start=1):
    print(f"{number}. {item}")

for i, item in enumerate(menu):
    print(f"menu[{i}] is {item}")

for i in range(len(prices)):
    prices[i] *= 2

print("Doubled:", *prices)

practice.solution:
players = ["Chloe", "Ana", "Ben", "Dev"]
scores = [92, 88, 75, 60]

for rank, player in enumerate(players, start=1):
    print(f"{rank}. {player}")

for i, player in enumerate(players):
    print(f"players[{i}] is {player}")

for i in range(len(scores)):
    scores[i] += 5

print("With bonus:", *scores)
